-- name: UpsertValue :exec
INSERT INTO settings_values (
	id,
	scope,
	definition_id,
	subject_type,
	subject_id,
	value
) VALUES (
	sqlc.arg(id),
	sqlc.arg(scope),
	sqlc.arg(definition_id),
	sqlc.arg(subject_type),
	sqlc.arg(subject_id),
	sqlc.arg(value)
)
ON CONFLICT (scope, subject_type, subject_id, definition_id) DO UPDATE SET
	value = EXCLUDED.value,
	archived_at = NULL,
	last_updated_at = CURRENT_TIMESTAMP;

